// Copies the design spec (doodle-ui) e-mail templates (email/<kind>.<lang>.html|txt + strings.<lang>.json, generated by its
// src/build.js) into src/lib/email/templates.ts as string constants (no runtime fs → works in serverless bundles), and the
// logo PNGs into public/email-assets/. Usage: node scripts/sync-email-templates.mjs [path/to/doodle-ui/email]
import fs from 'node:fs';
import path from 'node:path';
const src = process.argv[2] || '../doodle-ui/email';
const LANGS = ['en', 'da', 'fr', 'de'];
const fx = (l, t) => (l === 'fr' ? frTxt(t) : t);
// French typography: a space before ':' in the plain-text labels (upstream build.js hardcodes 'Label: url' for all languages – reported to Doodle UI).
const frTxt = (t) => t.replace(/([\p{L})])(:) (?=\{\{|https?:)/gu, '$1 $2 ');
const read = (f) => fs.readFileSync(path.join(src, f), 'utf8');
const all = {};
for (const l of LANGS) {
  all[l] = {
    invitation: { html: read(`invitation.${l}.html`), text: fx(l, read(`invitation.${l}.txt`)) },
    reminder: { html: read(`reminder.${l}.html`), text: fx(l, read(`reminder.${l}.txt`)) },
    organizerLinks: { html: read(`organizer-links.${l}.html`), text: fx(l, read(`organizer-links.${l}.txt`)) },
    strings: JSON.parse(read(`strings.${l}.json`)),
  };
}
const out = `// GENERATED by scripts/sync-email-templates.mjs from the design spec (doodle-ui) email/ – do not edit by hand.
export const TEMPLATES = ${JSON.stringify(all, null, 2)} as const;
`;
fs.writeFileSync('src/lib/email/templates.ts', out);
fs.mkdirSync('public/email-assets', { recursive: true });
for (const f of fs.readdirSync(path.join(src, 'assets'))) if (f.endsWith('.png')) fs.copyFileSync(path.join(src, 'assets', f), path.join('public/email-assets', f));
console.log('email templates synced');
